def main():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        print("True")
        return

    n = int(data[0])

    if n == 0:
        print("True")
        return

    nodes = []
    children = set()

    idx = 1
    for i in range(n):
        val = int(data[idx])
        left = int(data[idx + 1])
        right = int(data[idx + 2])
        idx += 3
        nodes.append((val, left, right))
        if left != -1:
            children.add(left)
        if right != -1:
            children.add(right)

    root = None
    all_values = set()
    for val, _, _ in nodes:
        all_values.add(val)

    for val in all_values:
        if val not in children:
            root = val
            break

    children_map = {}
    for val, left, right in nodes:
        children_map[val] = (left, right)

    def check_height(node):
        if node == -1 or node not in children_map:
            return (0, True)

        left_val, right_val = children_map[node]

        left_height, left_balanced = check_height(left_val)
        if not left_balanced:
            return (-1, False)

        right_height, right_balanced = check_height(right_val)
        if not right_balanced:
            return (-1, False)

        if abs(left_height - right_height) > 1:
            return (-1, False)

        return (max(left_height, right_height) + 1, True)

    _, balanced = check_height(root)
    print("True" if balanced else "False")

if __name__ == "__main__":
    main()
